window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-11eba7e67ebfd8b6"]={"versions": [{"id": "FIG-11eba7e67ebfd8b6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktionen / Kontrollknoten:</li>\n<li>Startknoten (from WAKEUP)</li>\n<li>Aktion <code>Decrement Divisor Counter</code></li>\n<li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code></li>\n<li>Aktion <code>Get succeeding sleep mode</code></li>\n<li>Aktion <code>Preload divisor counter for new sleep mode</code></li>\n<li>Endknoten (<code>Activity Final</code>)</li>\n<li>Datenobjekte und Konfigurationsstrukturen:</li>\n<li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.</li>\n<li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.</li>\n<li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.</li>\n<li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.</li>\n<li>Auswertung des Verzweigungsknotens:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.</li>\n<li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt):</li>\n</ul>\n<p class=\"fig-p\">a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.</p>\n<p class=\"fig-p\">b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.</p>\n<p class=\"fig-p\">c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}, {"id": "FIG-36f45b440ad5d339", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktionen / Kontrollknoten:</li>\n<li>Startknoten (from WAKEUP)</li>\n<li>Aktion <code>Decrement Divisor Counter</code></li>\n<li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code></li>\n<li>Aktion <code>Get succeeding sleep mode</code></li>\n<li>Aktion <code>Preload divisor counter for new sleep mode</code></li>\n<li>Endknoten (<code>Activity Final</code>)</li>\n<li>Datenobjekte und Konfigurationsstrukturen:</li>\n<li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.</li>\n<li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.</li>\n<li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.</li>\n<li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.</li>\n<li>Auswertung des Verzweigungsknotens:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.</li>\n<li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt):</li>\n</ul>\n<p class=\"fig-p\">a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.</p>\n<p class=\"fig-p\">b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.</p>\n<p class=\"fig-p\">c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}, {"id": "FIG-eb8fa6c6fa86b550", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktionen / Kontrollknoten:</li>\n<li>Startknoten (from WAKEUP)</li>\n<li>Aktion <code>Decrement Divisor Counter</code></li>\n<li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code></li>\n<li>Aktion <code>Get succeeding sleep mode</code></li>\n<li>Aktion <code>Preload divisor counter for new sleep mode</code></li>\n<li>Endknoten (<code>Activity Final</code>)</li>\n<li>Datenobjekte und Konfigurationsstrukturen:</li>\n<li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.</li>\n<li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.</li>\n<li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.</li>\n<li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.</li>\n<li>Auswertung des Verzweigungsknotens:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.</li>\n<li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt):</li>\n</ul>\n<p class=\"fig-p\">a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.</p>\n<p class=\"fig-p\">b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.</p>\n<p class=\"fig-p\">c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}], "trans": [{"from": "FIG-11eba7e67ebfd8b6", "to": "FIG-36f45b440ad5d339", "fr": "R4.0.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildzuschnitt bzw. Ränder leicht vergrößert (von 804x410 auf 828x420 Pixel), wodurch die untere Beschriftung des Activity-Final-Knotens minimal verschoben bzw. abgeschnitten ist.</li>\n</ul>"}, {"from": "FIG-36f45b440ad5d339", "to": "FIG-eb8fa6c6fa86b550", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
